function value(c) {
  if (c === "I") {
    return 1;
  } else if (c === "V") {
    return 5;
  } else if (c === "X") {
    return 10;
  } else if (c === "L") {
    return 50;
  } else if (c === "C") {
    return 100;
  } else if (c === "D") {
    return 500;
  } else if (c === "M") {
    return 1000;
  }
  return 0;
}

var numeral = "XLII";
var total = 0;
for (var i = 0; i < numeral.length; i++) {
  var current = value(numeral.charAt(i));
  var next = value(numeral.charAt(i + 1));
  total += next > current ? -current : current;
}
console.log(total);

