var values = { I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000 };
var numeral = "XLII";
var total = 0;
for (var i = 0; i < numeral.length; i++) {
  var current = values[numeral.charAt(i)];
  var next = values[numeral.charAt(i + 1)];
  total += next > current ? -current : current;
}
console.log(total);
